import React from "react";

function BrowseType() {
  return (
    <div className="BrowseType w-full h-60">
      <div className="h-10 flex justify-start pl-20">
        <h1 className="font-medium text-3xl">Browse by Type</h1>
      </div>
      
      <div className="h-48 flex justify-center items-center">
        <div className="grid grid-cols-5 gap-4 w-[90%] max-w-6xl">
          {/* Тип 1 */}
          <div className="bg-white/80 backdrop-blur-md border border-gray-300 rounded-lg flex items-center justify-center h-28 shadow">
            <span className="text-gray-700 font-medium">Sedan</span>
          </div>
          
          {/* Тип 2 */}
          <div className="bg-white/80 backdrop-blur-md border border-gray-300 rounded-lg flex items-center justify-center h-28 shadow">
            <span className="text-gray-700 font-medium">SUV</span>
          </div>

          {/* Тип 3 */}
          <div className="bg-white/80 backdrop-blur-md border border-gray-300 rounded-lg flex items-center justify-center h-28 shadow">
            <span className="text-gray-700 font-medium">Coupe</span>
          </div>

          {/* Тип 4 */}
          <div className="bg-white/80 backdrop-blur-md border border-gray-300 rounded-lg flex items-center justify-center h-28 shadow">
            <span className="text-gray-700 font-medium">Truck</span>
          </div>

          {/* Тип 5 */}
          <div className="bg-white/80 backdrop-blur-md border border-gray-300 rounded-lg flex items-center justify-center h-28 shadow">
            <span className="text-gray-700 font-medium">Convertible</span>
          </div>
        </div>
      </div>
    </div>
  );
}

export default BrowseType;
